// Estado inicial da paginação — viaja dentro dos itens daqui em diante
const busca = $('Resolver Código IBGE1').first().json;
const impResp = $('Criar Importação1').first().json;
const importacaoId = Array.isArray(impResp) ? impResp[0]?.id : impResp.id;
if (!importacaoId) throw new Error('Importação não retornou id (confira o header Prefer: return=representation)');
const listId = $('Consolidar Lista').first().json.list_id || null;

return [{ json: { state: {
  importacao_id: importacaoId,
  token: null,
  ultimo_token: null,
  paginas: 0,
  acumulado: 0,
  maximo: busca.maximo,
  cnaes: busca.cnae,
  codigo_ibge: busca.codigo_ibge,
  list_id: listId
} } }];

// Resolve o código IBGE da cidade
const form = $('Formulário Busca1').first().json;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const alvo = norm(form['Cidade']);

const municipios = $input.all().map(i => i.json);
const m = municipios.find(x => norm(x.nome) === alvo);
if (!m) throw new Error(`Cidade "${form['Cidade']}" não encontrada em ${form['Estado (UF)']}`);

const maximo = Math.max(1, parseInt(form['Máximo de registros'], 10) || 100);
const cnaes = String(form['CNAE']).split(',').map(c => c.replace(/\D/g, '')).filter(Boolean).join(',');
if (!cnaes) throw new Error('CNAE inválido');

return [{ json: {
  cnae: cnaes,
  uf: form['Estado (UF)'].trim().toUpperCase(),
  cidade: form['Cidade'].trim(),
  codigo_ibge: Number(m.id),
  maximo
} }];

// Monta a query da página atual (token é mutuamente exclusivo com filtros)
const st = $json.state;
if (!st) throw new Error('Estado da paginação ausente');
const restante = st.maximo - st.acumulado;
const limit = Math.min(100, Math.max(1, restante));

let qs;
if (st.token) {
  qs = { token: st.token, limit };
} else {
  qs = {
    'mainActivity.id.in': st.cnaes,
    'status.id.in': 2,
    'address.municipality.in': Number(st.codigo_ibge),
    'phones.ex': true,
    limit
  };
  if (st.list_id) qs['taxId.nin'] = st.list_id;
}
return [{ json: { qs, state: st } }];

// Mapeia a resposta do CNPJá em linhas de empresas+socios e
// calcula o novo estado da paginação (anexado em __state a cada item)
const stAnterior = $('Preparar Página1').first().json.state;
const body = $input.first().json;
const recs = body.records || body.data || (Array.isArray(body) ? body : []);

const novoToken = body.next || body.token || null;
const state = {
  ...stAnterior,
  token: novoToken,
  ultimo_token: novoToken || stAnterior.ultimo_token,
  paginas: (stAnterior.paginas || 0) + 1,
  acumulado: (stAnterior.acumulado || 0) + recs.length
};

const slugify = s => String(s || '').toLowerCase()
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
  .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');
const CONTAB = /contab|contad|assessoria|escritorio/i;
const cap = s => s ? s.charAt(0).toUpperCase() + s.slice(1).toLowerCase() : s;

// Normaliza telefones: celular de 8 dígitos iniciando em 6/7/8/9
// é formato antigo (pré-2016) e ganha o 9 na frente
const normTel = t => {
  const num = String(t.number || '').replace(/\D/g, '');
  if (num.length === 9 && /^9/.test(num)) return { ...t, number: num, celular: true };
  if (num.length === 8 && /^[6-9]/.test(num)) return { ...t, number: '9' + num, celular: true };
  return { ...t, number: num, celular: false };
};

const out = [];
for (const o of recs) {
  const telsN = (o.phones || []).map(normTel);
  const mails = o.emails || [];
  const cel = telsN.find(t => t.celular);
  const telPrincipal = cel || telsN[0] || null;
  const mailBom = mails.find(m => !CONTAB.test(m.address || '') && String(m.ownership || '').toUpperCase() !== 'ACCOUNTING');
  const mailEscolhido = mailBom || mails[0] || null;

  const socios = (o.company?.members || []).map(mb => ({
    person_id: mb.person?.id || null,
    nome: mb.person?.name || null,
    faixa_etaria: mb.person?.age || null,
    identificador: mb.person?.type || null,
    papel: mb.role?.text || null,
    qualificacao: mb.role?.text || null,
    qualificacao_codigo: mb.role?.id ?? null,
    data_entrada: mb.since || null
  }));

  const socioPF = socios.find(s => String(s.identificador || '').toUpperCase() === 'NATURAL');
  const primeiroNome = socioPF?.nome ? cap(socioPF.nome.split(' ')[0]) : null;
  const nomeExib = o.alias || primeiroNome || o.company?.name || null;

  out.push({ json: {
    __state: state,
    empresa: {
      cnpj: o.taxId,
      cnpj_raiz: String(o.taxId || '').slice(0, 8),
      nome_fantasia: o.alias || null,
      razao_social: o.company?.name || null,
      nome_exibicao: nomeExib,
      nome_socio: socioPF?.nome ? socioPF.nome.split(' ').slice(0, 2).map(cap).join(' ') : null,
      slug: slugify(`${nomeExib}-${o.address?.city}-${String(o.taxId||'').slice(-4)}`),
      matriz_filial: o.head ? 'MATRIZ' : 'FILIAL',
      situacao_codigo: o.status?.id ?? null,
      situacao: o.status?.text || null,
      situacao_data: o.statusDate || null,
      motivo_codigo: o.reason?.id ?? null,
      situacao_motivo: o.reason?.text || null,
      data_abertura: o.founded || null,
      natureza_codigo: o.company?.nature?.id ?? null,
      natureza_juridica: o.company?.nature?.text || null,
      porte_codigo_num: o.company?.size?.id ?? null,
      porte_descricao: o.company?.size?.text || null,
      capital_social: o.company?.equity ?? null,
      simples: o.company?.simples?.optant ?? null,
      simples_desde: o.company?.simples?.since || null,
      mei: o.company?.simei?.optant ?? null,
      mei_desde: o.company?.simei?.since || null,
      cnae_principal: String(o.mainActivity?.id ?? ''),
      cnae_descricao: o.mainActivity?.text || null,
      cnaes_secundarios: o.sideActivities || [],
      cep: o.address?.zip || null,
      logradouro: o.address?.street || null,
      numero: o.address?.number || null,
      complemento: o.address?.details || null,
      bairro: o.address?.district || null,
      municipio: o.address?.city || null,
      uf: o.address?.state || null,
      codigo_ibge: o.address?.municipality ?? null,
      telefones_json: telsN,
      emails_json: mails,
      telefone_original: telPrincipal ? `(${telPrincipal.area}) ${telPrincipal.number}` : null,
      whatsapp: cel ? `55${cel.area}${cel.number}` : null,
      tem_celular: !!cel,
      email: mailEscolhido?.address || null,
      email_contab: !!mailEscolhido && (CONTAB.test(mailEscolhido.address || '') || String(mailEscolhido.ownership || '').toUpperCase() === 'ACCOUNTING'),
      fonte_atualizado_em: o.updated || null,
      origem: 'cnpja',
      importacao_id: state.importacao_id,
      status: 'novo'
    },
    socios
  }});
}

if (out.length === 0) return [{ json: { __vazio: true, __state: state } }];
return out;

// Junta TODOS os sócios da página num único lote,
// emparelhando com o id retornado do upsert (vazio = empresa já existia)
const upserts = $input.all();
const mapeados = $('Mapear Registros1').all().filter(i => i.json.empresa !== undefined);
const rows = [];
for (let i = 0; i < upserts.length; i++) {
  const resp = upserts[i].json;
  const criado = Array.isArray(resp) ? resp[0] : resp;
  if (!criado || !criado.id) continue;
  const socios = mapeados[i]?.json?.socios || [];
  for (const s of socios) {
    if (!s.nome) continue;
    rows.push({
      person_id: s.person_id,
      nome: s.nome,
      faixa_etaria: s.faixa_etaria,
      identificador: s.identificador,
      papel: s.papel,
      qualificacao: s.qualificacao,
      qualificacao_codigo: s.qualificacao_codigo,
      data_entrada: s.data_entrada,
      empresa_id: criado.id
    });
  }
}
return [{ json: { socios_lote: rows } }];

// Decide se busca a próxima página (estado vem do Mapear Registros)
const st = $('Mapear Registros1').first().json.__state;
const continuar = !!st.token && st.acumulado < st.maximo && st.paginas < 10;

// --- INSTRUMENTAÇÃO (13/08/2026) ---------------------------------------
// Conta o resultado REAL do upsert desta página e acumula no estado, que já
// dá a volta no laço. NÃO altera `continuar` nem nenhuma chave existente:
// só acrescenta inseridos_acum, rejeitados_acum e rejeicoes_motivo.
//
// Guarda __vazio: quando a página vem sem registros, o fluxo vai direto de
// `Tem registros?1` para cá, SEM passar pelo upsert — e $('Upsert Empresas1')
// .all() devolveria os itens da página ANTERIOR, contando tudo duas vezes.
const vazia = $('Mapear Registros1').first().json.__vazio === true;
let ins = 0, rej = 0;
const motivos = {};
if (!vazia) {
  for (const it of $('Upsert Empresas1').all()) {
    const j = (it && it.json) || {};
    if (j.code) {                      // PostgREST devolveu erro (neverError:true)
      rej++;
      const m = j.message && /constraint "([^"]+)"/.exec(j.message);
      const cod = String(j.code);
      const alvo = m ? m[1] : 'sem_constraint_nomeada';
      motivos[cod] = motivos[cod] || {};
      motivos[cod][alvo] = (motivos[cod][alvo] || 0) + 1;
    } else {
      ins++;
    }
  }
}

const motivosAcum = {};
for (const c in (st.rejeicoes_motivo || {})) motivosAcum[c] = { ...st.rejeicoes_motivo[c] };
for (const c in motivos) {
  motivosAcum[c] = motivosAcum[c] || {};
  for (const a in motivos[c]) motivosAcum[c][a] = (motivosAcum[c][a] || 0) + motivos[c][a];
}

const state = {
  ...st,
  inseridos_acum:   (st.inseridos_acum   || 0) + ins,
  rejeitados_acum:  (st.rejeitados_acum  || 0) + rej,
  rejeicoes_motivo: motivosAcum
};
return [{ json: { continuar, state } }];

// Resumo final da importação
// INSTRUMENTAÇÃO (13/08/2026): `total_gravados` passou a ser INSERT REAL.
// Antes desta data ele carregava `acumulado` — o que o CNPJá devolveu — e
// errava sempre para mais. O número da API foi para `total_api`, coluna que
// existia em `importacoes` e nunca havia sido preenchida.
// `creditos_custo` continua sobre `acumulado`, e isso está CERTO: paga-se o
// que a API devolve, não o que entra no banco.
const st = $json.state;
const api = st.acumulado || 0;
const ins = st.inseridos_acum || 0;
const rej = st.rejeitados_acum || 0;
return [{ json: {
  importacao_id: st.importacao_id,
  total_api: api,
  total_gravados: ins,
  rejeitados_constraint: rej,
  rejeicoes_por_motivo: st.rejeicoes_motivo || {},
  conferencia: (api - rej) === ins ? 'ok' : 'DIVERGENTE: api-rejeitados != inseridos',
  paginas_lidas: st.paginas || 0,
  creditos_custo: Math.ceil(api / 10),
  cursor_token: st.ultimo_token || null
} }];

// Junta config + CNPJs da base e decide: criar ou atualizar a lista no CNPJá
const cfg = $('Buscar Config Lista').all().map(i => i.json).flat().filter(r => r && r.valor);
const listId = cfg[0]?.valor || null;
const cnpjs = $input.all().map(i => i.json).flat()
  .filter(r => r && r.cnpj)
  .map(r => String(r.cnpj).replace(/\D/g, ''))
  .filter(c => c.length === 14);
return [{ json: { existe: !!listId, list_id: listId, cnpjs, total_cnpjs: cnpjs.length } }];

// Resolve o list_id independente do caminho (criada agora ou já existente)
const prep = $('Preparar Lista Exclusão').first().json;
let listId = prep.list_id;
if (!listId) {
  try {
    const criada = $('Criar Lista CNPJá').first().json;
    listId = (Array.isArray(criada) ? criada[0]?.id : criada.id) || null;
  } catch (e) { listId = null; }
}
return [{ json: { list_id: listId, total_cnpjs_excluidos: prep.total_cnpjs } }];
